import React, { useState } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const StudentDashboard = () => {
  const { user, logout } = useAuth(); // get user + logout from context
  const navigate = useNavigate();
  const [showPinModal, setShowPinModal] = useState(false);
  const [pinForm, setPinForm] = useState({
    currentPin: '',
    newPin: '',
    confirmPin: '',
  });
  const [pinStatus, setPinStatus] = useState({ type: '', message: '' });
  const [isSubmittingPin, setIsSubmittingPin] = useState(false);

  const handleLogout = () => {
    // Clear tokens from localStorage
    localStorage.removeItem('accessToken');
    localStorage.removeItem('refreshToken');
    localStorage.removeItem('userRole');

    // Clear auth context if using it
    if (logout) logout(); // optional, based on your context

    // Navigate to login page
    navigate('/');
  };

  const handlePinInput = (event) => {
    const { name, value } = event.target;
    setPinForm((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const closePinModal = () => {
    setShowPinModal(false);
    setPinForm({ currentPin: '', newPin: '', confirmPin: '' });
  };

  const handlePinSubmit = async (event) => {
    event.preventDefault();
    setPinStatus({ type: '', message: '' });

    if (pinForm.newPin !== pinForm.confirmPin) {
      setPinStatus({ type: 'error', message: 'New PIN and confirm PIN must match.' });
      return;
    }

    if (!/^\d{4,6}$/.test(pinForm.newPin)) {
      setPinStatus({ type: 'error', message: 'PIN must be a 4 or 6 digit number.' });
      return;
    }

    setIsSubmittingPin(true);
    try {
      const token = localStorage.getItem('accessToken');
      await axios.post(
        'http://localhost:8000/api/change-pin/',
        {
          current_pin: pinForm.currentPin,
          new_pin: pinForm.newPin,
          confirm_pin: pinForm.confirmPin,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setPinStatus({ type: 'success', message: 'PIN updated successfully.' });
      closePinModal();
    } catch (error) {
      const serverMessage =
        error.response?.data?.detail ||
        error.response?.data?.message ||
        'Failed to update PIN. Please try again.';
      setPinStatus({ type: 'error', message: serverMessage });
    } finally {
      setIsSubmittingPin(false);
    }
  };

  return (
    <div className="d-flex">
      {/* Sidebar */}
      <div className="bg-danger text-white d-flex flex-column align-items-center p-3" style={{ width: '250px', minHeight: '100vh' }}>
        
        <h5 className="fw-bold mb-0">{user?.first_name || user?.username || 'User'}</h5>
        

        <ul className="nav flex-column w-100 text-center">
          <li className="nav-item mb-2"><span className="nav-link text-white">Dashboard</span></li>
          <li className="nav-item mb-2"><span className="nav-link text-white">Profile Settings</span></li>
          <li className="nav-item mb-2">
            <button
              onClick={() => setShowPinModal(true)}
              className="nav-link text-white btn btn-link p-0 w-100"
            >
              Change Pin
            </button>
          </li>
          <li className="nav-item mt-3">
            <button
              onClick={handleLogout}
              className="nav-link text-white btn btn-link p-0 w-100"
            >
              Logout
            </button>
          </li>
        </ul>
      </div>

      {/* Main Content */}
      <div className="flex-grow-1 bg-light p-5">
        <h4 className="fw-bold">Welcome <span className="text-danger">{user?.first_name || user?.username}</span>!</h4>
        <p className="text-muted mb-4">Stay Organised, Stay Ahead</p>

        {pinStatus.message && (
          <div className={`alert ${pinStatus.type === 'error' ? 'alert-danger' : 'alert-success'}`} role="alert">
            {pinStatus.message}
          </div>
        )}

        <div className="row g-4">
          <div className="col-md-6">
            <div className="card bg-danger text-white shadow h-100">
              <div className="card-body d-flex flex-column">
                <h5 className="card-title fw-bold">Teachers Timetable</h5>
                <p className="card-text small flex-grow-1">Need to meet a teacher? Check free slots and cabin location.</p>
                <button
                  onClick={() => navigate('/faculty-timetable')}
                  className="btn btn-light btn-sm fw-bold mt-3"
                >
                  Check Availability
                </button>
              </div>
            </div>
          </div>

          <div className="col-md-6" id="change-pin-card">
            <div className="card bg-white shadow h-100">
              <div className="card-body d-flex flex-column">
                <h5 className="card-title fw-bold text-danger">Change PIN</h5>
                <p className="card-text small flex-grow-1">Securely update your student PIN whenever you need.</p>
                <button
                  onClick={() => setShowPinModal(true)}
                  className="btn btn-danger btn-sm fw-bold mt-3"
                >
                  Update PIN
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      {showPinModal && (
        <div
          className="position-fixed top-0 start-0 w-100 h-100 d-flex align-items-center justify-content-center"
          style={{ backgroundColor: 'rgba(0, 0, 0, 0.5)', zIndex: 1050 }}
        >
          <div className="bg-white rounded shadow p-4 w-100" style={{ maxWidth: '420px' }}>
            <div className="d-flex justify-content-between align-items-center mb-3">
              <h5 className="mb-0">Change PIN</h5>
              <button type="button" className="btn-close" aria-label="Close" onClick={closePinModal}></button>
            </div>
            <form onSubmit={handlePinSubmit}>
              <div className="mb-3">
                <label htmlFor="currentPin" className="form-label">Current PIN</label>
                <input
                  type="password"
                  className="form-control"
                  id="currentPin"
                  name="currentPin"
                  value={pinForm.currentPin}
                  onChange={handlePinInput}
                  placeholder="Enter current PIN"
                />
              </div>
              <div className="mb-3">
                <label htmlFor="newPin" className="form-label">New PIN</label>
                <input
                  type="password"
                  className="form-control"
                  id="newPin"
                  name="newPin"
                  value={pinForm.newPin}
                  onChange={handlePinInput}
                  placeholder="Enter new PIN"
                  required
                />
              </div>
              <div className="mb-4">
                <label htmlFor="confirmPin" className="form-label">Confirm PIN</label>
                <input
                  type="password"
                  className="form-control"
                  id="confirmPin"
                  name="confirmPin"
                  value={pinForm.confirmPin}
                  onChange={handlePinInput}
                  placeholder="Confirm new PIN"
                  required
                />
              </div>
              <div className="d-flex justify-content-end gap-2">
                <button type="button" className="btn btn-outline-secondary" onClick={closePinModal}>
                  Cancel
                </button>
                <button type="submit" className="btn btn-danger" disabled={isSubmittingPin}>
                  {isSubmittingPin ? 'Updating...' : 'Save PIN'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentDashboard;
